; FF1 native engine: talking to map objects. Our own code, written from what FF1's talk
; routines do (disassembly bank 0E, TalkRoutines). Each object id has a routine kind and four
; bytes of talk data (dialogue numbers, a condition's object or item) from the ROM; the
; routines' own constants (object ids, battles, teleports, item addresses) are the ROM's,
; generated by build.py as TK_<routine>_<n> (talkconst.py: the n-th operand in code order).
; Common bank: $5800 talk data (4 x 208), $5C00 kind per object id, $5D00 weapon slots (16).
C_TALKDAT  = $5800
C_TALKKIND = $5C00
C_WPNSLOT  = $5D00
GF_VIS     = $01            ; game flag bits: object visible, event done
GF_EVENT   = $02

section bank 0, $2000
; HL = slot -> A = the dialogue to print (and the routine's effects)
talk_obj:   ld a, l
            ld [talk_slot], a
            ld a, [hl]                      ; object id
            ld [talk_id], a
            ld l, a                         ; talk data -> talk_d (4 bytes)
            ld h, 0
            add hl, hl
            add hl, hl
            ld de, C_TALKDAT
            add hl, de
            ld a, COMMON
            call sbank
            ld de, talk_d
            ld b, 4
.c:         ld a, [hl+]
            ld [de], a
            inc de
            dec b
            jr nz, .c
            ld a, [talk_id]                 ; the routine kind -> jump
            ld l, a
            ld h, high(C_TALKKIND)
            ld a, [hl]
            add a, a
            ld l, a
            ld h, 0
            ld de, talk_tbl
            add hl, de
            ld a, [hl+]
            ld h, [hl]
            ld l, a
            jp hl

talk_tbl:   dw t_none, t_king, t_garland, t_princess1, t_bikke, t_elfdoc, t_elfprince, t_astos
            dw t_nerrick, t_smith, t_matoya, t_unne, t_vampire, t_sarda, t_bahamut, t_ifvis
            dw t_subeng, t_cubebot, t_princess2, t_fairy, t_titan, t_canoesage, t_norm, t_replace
            dw t_fight, t_none, t_ifitem, t_invis, t_ifbridge, t_ifevent, t_gobridge, t_4orb
            dw t_cooguy, t_ifcanoe, t_ifcanal, t_ifkeytnt, t_ifearthvamp, t_ifairship
            dw t_ifearthfire, t_cubebotbad, t_chime, t_blackorb

; ---- helpers (FF1: CheckGameEventFlag, SetGameEventFlag, IsObjectVisible, ShowMapObject,
; HideMapObject, HideThisMapObject, TalkBattle, TalkNormTeleport)
d1:         ld a, [talk_d + 1]
            ret
d2:         ld a, [talk_d + 2]
            ret
d3:         ld a, [talk_d + 3]
            ret
fanfare:    ld hl, dlgsfx
            inc [hl]
            ret
; C = event flag of object A
ev_check:   ld l, a
            ld h, high(game_flags)
            ld a, [hl]
            rrca
            rrca
            ret
ev_set:     ld l, a
            ld h, high(game_flags)
            set 1, [hl]
            ret
; C = object A visible
is_vis:     ld l, a
            ld h, high(game_flags)
            ld a, [hl]
            rrca
            ret
; object A visible: its flag, and a slot on this map with that raw id shown
show_obj:   ld c, a
            ld l, a
            ld h, high(game_flags)
            set 0, [hl]
            ld hl, objs
            ld b, 15
.l:         push hl
            ld de, O_RAW
            add hl, de
            ld a, [hl]
            pop hl
            cp c
            jr nz, .n
            ld [hl], c
            ret
.n:         ld de, O_SIZE
            add hl, de
            dec b
            jr nz, .l
            ret
; object A hidden: its flag, and every slot showing it
hide_obj:   ld c, a
            ld l, a
            ld h, high(game_flags)
            res 0, [hl]
            ld hl, objs
            ld b, 15
.l:         ld a, [hl]
            cp c
            jr nz, .n
            ld [hl], 0
.n:         ld de, O_SIZE
            add hl, de
            dec b
            jr nz, .l
            ret
; the object talked to hidden (its id A)
hide_this:  ld l, a
            ld h, high(game_flags)
            res 0, [hl]
            ld a, [talk_slot]
            ld l, a
            ld h, high(objs)
            ld [hl], 0
            ret
; a battle with formation A when the box closes
talk_btl:   ld [pend_btl], a
            ld a, 1
            ld [pend_btlf], a
            ret
; a normal teleport A when the box closes
talk_tele:  ld [pend_tele], a
            ld a, 1
            ld [pend_telef], a
            ret
; A = an item / flag byte at a save-RAM address (HL)
item_inc:   inc [hl]
            ret
item_dec:   dec [hl]
            ret

; ---- the routines (FF1's TalkRoutines)
t_none:     xor a
            ret
t_norm:     jp d1

t_king:     ld a, TK_Talk_KingConeria_0     ; princess (rescued) visible?
            call is_vis
            jp nc, d1
            ld a, [TK_Talk_KingConeria_1]   ; bridge
            and a
            jp nz, d3
            ld hl, TK_Talk_KingConeria_2
            inc [hl]                        ; the bridge appears
            call fanfare
            jp d2

t_garland:  ld a, TK_Talk_Garland_0
            call hide_this
            ld a, TK_Talk_Garland_1
            call talk_btl
            jp d1

t_princess1:
            ld a, TK_Talk_Princess1_0
            call hide_this
            ld a, TK_Talk_Princess1_1
            call show_obj
            ld a, TK_Talk_Princess1_2
            call talk_tele
            jp d1

t_bikke:    ld a, TK_Talk_Bikke_0
            call ev_check
            jr c, .fought
            ld a, TK_Talk_Bikke_0
            call ev_set
            ld a, TK_Talk_Bikke_1
            call talk_btl
            jp d1
.fought:    ld a, [TK_Talk_Bikke_2]         ; ship
            and a
            jp nz, d3
            ld hl, TK_Talk_Bikke_3
            inc [hl]
            ld a, TK_Talk_Bikke_4
            call show_obj
            ld a, TK_Talk_Bikke_5
            call show_obj
            ld a, TK_Talk_Bikke_6
            call show_obj
            call fanfare
            jp d2

t_elfdoc:   ld a, TK_Talk_ElfDoc_0
            call ev_check
            jp c, d3
            ld a, [TK_Talk_ElfDoc_1]        ; herb
            and a
            jp z, d1
            ld hl, TK_Talk_ElfDoc_2
            dec [hl]
            ld a, TK_Talk_ElfDoc_0
            call ev_set
            call fanfare
            jp d2

t_elfprince:
            ld a, TK_Talk_ElfPrince_0
            call ev_check
            jp nc, d3
            ld a, [TK_Talk_ElfPrince_1]     ; mystic key
            and a
            jp nz, d2
            ld hl, TK_Talk_ElfPrince_2
            inc [hl]
            call fanfare
            jp d1

t_astos:    ld a, [TK_Talk_Astos_0]         ; crown
            and a
            jp z, d1
            ld hl, TK_Talk_Astos_1          ; crystal
            inc [hl]
            ld a, TK_Talk_Astos_2
            call hide_this
            ld a, TK_Talk_Astos_3
            call talk_btl
            call fanfare
            jp d2

t_nerrick:  ld a, [TK_Talk_Nerrick_0]       ; TNT
            and a
            jp z, d1
            ld hl, TK_Talk_Nerrick_1
            dec [hl]
            ld a, TK_Talk_Nerrick_2
            ld [TK_Talk_Nerrick_3], a       ; the canal opens
            ld a, TK_Talk_Nerrick_4
            call hide_this
            call fanfare
            jp d2

t_smith:    ld a, TK_Talk_Smith_0
            call ev_check
            jp c, d3
            ld a, [TK_Talk_Smith_1]         ; adamant
            and a
            jp z, d1
            ld a, COMMON                    ; the first empty weapon slot of the party
            call sbank
            ld hl, C_WPNSLOT
            ld b, 16
.s:         ld a, [hl+]
            ld e, a
            ld d, high(TK_Talk_Smith_3)     ; (ch_stats)
            ld a, [de]
            and a
            jr z, .found
            dec b
            jr nz, .s
            ld a, TK_Talk_Smith_6           ; no room: "don't be greedy"
            ret
.found:     ld a, TK_Talk_Smith_2           ; the sword
            ld [de], a
            ld a, TK_Talk_Smith_4
            call ev_set
            ld hl, TK_Talk_Smith_5
            dec [hl]
            call fanfare
            jp d2

t_matoya:   ld a, [TK_Talk_Matoya_0]        ; herb
            and a
            jp nz, d3
            ld a, [TK_Talk_Matoya_1]        ; crystal
            and a
            jr nz, .ex
            ld a, TK_Talk_Matoya_2
            call ev_check
            jp c, d3
            jp d1
.ex:        ld hl, TK_Talk_Matoya_3
            inc [hl]
            ld hl, TK_Talk_Matoya_4
            dec [hl]
            call fanfare
            jp d2

t_unne:     ld a, TK_Talk_Unne_0
            call ev_check
            jp c, d3
            ld a, [TK_Talk_Unne_1]          ; slab
            and a
            jp z, d1
            ld hl, TK_Talk_Unne_2
            dec [hl]
            ld a, TK_Talk_Unne_0
            call ev_set
            call fanfare
            jp d2

t_vampire:  ld a, TK_Talk_Vampire_0
            call hide_this
            ld a, TK_Talk_Vampire_1
            call talk_btl
            jp d1

t_sarda:    ld a, [TK_Talk_Sarda_0]         ; rod
            and a
            jp nz, d2
            ld a, TK_Talk_Sarda_1           ; vampire still there
            call is_vis
            jp c, d2
            ld hl, TK_Talk_Sarda_2
            inc [hl]
            call fanfare
            jp d1

t_bahamut:  ld a, TK_Talk_Bahamut_0
            call ev_check
            jp c, d3
            ld a, [TK_Talk_Bahamut_1]       ; tail
            and a
            jp z, d1
            ld hl, TK_Talk_Bahamut_2
            dec [hl]
            ld a, TK_Talk_Bahamut_0
            call ev_set
            call class_change
            call fanfare
            jp d2

t_ifvis:    ld a, [talk_d]
            call is_vis
            jp nc, d1
            jp d2

t_subeng:   ld a, [TK_Talk_SubEng_0]        ; oxyale
            and a
            jp z, d1
            ld a, TK_Talk_SubEng_1
            call hide_this
            jp d2

t_cubebot:  ld a, [TK_Talk_CubeBot_0]       ; cube
            and a
            jp nz, d2
            ld hl, TK_Talk_CubeBot_1
            inc [hl]
            call fanfare
            jp d1

t_cubebotbad:
            ld a, [TK_Talk_CubeBotBad_0]
            and a
            jp nz, d2
            ld hl, TK_Talk_CubeBotBad_1
            inc [hl]
            jp d1

t_princess2:
            ld a, [TK_Talk_Princess2_0]     ; lute
            and a
            jp nz, d2
            ld hl, TK_Talk_Princess2_1
            inc [hl]
            call fanfare
            jp d1

t_fairy:    ld a, [TK_Talk_Fairy_0]         ; oxyale
            and a
            jp nz, d2
            ld hl, TK_Talk_Fairy_1
            inc [hl]
            call fanfare
            jp d1

t_titan:    ld a, [TK_Talk_Titan_0]         ; ruby
            and a
            jp z, d1
            ld hl, TK_Talk_Titan_1
            dec [hl]
            ld a, TK_Talk_Titan_2
            call hide_this
            call fanfare
            jp d2

t_canoesage:
            ld a, [TK_Talk_CanoeSage_0]     ; canoe
            and a
            jp nz, d2
            ld a, [TK_Talk_CanoeSage_1]     ; earth orb
            and a
            jp z, d2
            ld hl, TK_Talk_CanoeSage_2
            inc [hl]
            call fanfare
            jp d1

t_replace:  ld a, [talk_d]
            call hide_this
            ld a, [talk_d + 3]
            call show_obj
            jp d1

t_cooguy:   ld a, [talk_d]
            call hide_this
            jp d1

t_fight:    ld a, [talk_d]
            call hide_this
            ld a, [talk_d + 3]
            call talk_btl
            jp d1

t_ifitem:   ld a, [talk_d]                  ; items[talk_d]
            add a, low(TK_Talk_ifitem_0)
            ld l, a
            ld h, high(TK_Talk_ifitem_0)
            ld a, [hl]
            and a
            jp nz, d1
            jp d2

t_invis:    ld a, TK_Talk_Invis_0
            call is_vis
            jp c, d2
            ld a, [TK_Talk_Invis_1]         ; lute
            and a
            jp nz, d2
            jp d1

t_ifbridge: ld a, [TK_Talk_ifbridge_0]
            and a
            jp nz, d1
            jp d2

t_ifevent:  ld a, [talk_d]
            call ev_check
            jp nc, d1
            jp d2

t_gobridge: ld a, TK_Talk_GoBridge_0
            call is_vis
            jp nc, d2
            ld a, [TK_Talk_GoBridge_1]
            and a
            jp nz, d2
            jp d1

t_4orb:     call all_orbs
            jp nz, d1
            jp d2

t_blackorb: call all_orbs
            jp z, d2
            ld a, TK_Talk_BlackOrb_4
            call hide_this
            call fanfare
            call fanfare
            jp d1

t_ifcanoe:  ld a, [TK_Talk_ifcanoe_0]
            and a
            jp nz, d1
            jp d2

t_ifcanal:  ld a, [TK_Talk_ifcanal_0]
            and a
            jp z, d1
            jp d2

t_ifkeytnt: ld a, [TK_Talk_ifkeytnt_0]      ; key and no TNT
            and a
            jp z, d2
            ld a, [TK_Talk_ifkeytnt_1]
            and a
            jp nz, d2
            jp d1

t_ifearthvamp:
            ld a, TK_Talk_ifearthvamp_0     ; vampire gone and no earth orb
            call is_vis
            jp c, d2
            ld a, [TK_Talk_ifearthvamp_1]
            and a
            jp nz, d2
            jp d1

t_ifairship:
            ld a, [TK_Talk_ifairship_0]
            and a
            jp z, d1
            jp d2

t_ifearthfire:
            ld a, [TK_Talk_ifearthfire_0]   ; earth orb and not the fire orb
            and a
            jp z, d2
            ld a, [TK_Talk_ifearthfire_1]
            and a
            jp nz, d2
            jp d1

t_chime:    ld a, TK_Talk_Chime_0
            call ev_check
            jp nc, d3
            ld a, [TK_Talk_Chime_1]         ; chime
            and a
            jp nz, d2
            ld hl, TK_Talk_Chime_2
            inc [hl]
            call fanfare
            jp d1

; NZ: all four orbs lit (FF1: AND of the four bytes)
all_orbs:   ld a, [TK_Talk_4Orb_0]
            ld hl, TK_Talk_4Orb_1
            and [hl]
            ld hl, TK_Talk_4Orb_2
            and [hl]
            ld hl, TK_Talk_4Orb_3
            and [hl]
            ret

; FF1's class change (Bahamut): every member's class + 6
class_change:
            ld hl, ch_stats
            ld b, 4
.l:         ld a, [hl]
            add a, 6
            ld [hl], a
            ld a, l
            add a, $40
            ld l, a
            dec b
            jr nz, .l
            ret

; the box closed: a teleport or battle the talk asked for
talk_after: ld a, [pend_telef]
            and a
            jr z, .b
            xor a
            ld [pend_telef], a
            ld a, [pend_tele]
            ld e, a
            ld d, $80                       ; as a normal teleport tile with that number
            jp do_tele
.b:         ld a, [pend_btlf]
            and a
            ret z
            xor a
            ld [pend_btlf], a               ; (battles: battle.s, later)
            ret

; ---- treasure chests (FF1 OpenTreasureChest): A = chest number -> A = the dialogue
NAMES      = 4                  ; names bank: $4000 name pointers, $7000 prices, $7200 chests
N_PRICE    = $7000
N_TREAS    = $7200
ITEMS      = $D020              ; (FF1 items = save page + $20; gold = + $1C, 3 bytes)
GOLD       = $D01C
DLG_TCGET  = $F0
DLG_FULL   = $F1
DLG_EMPTY  = $F2
open_chest: ld [tc_id], a
            ld l, a
            ld h, high(game_flags)
            bit 2, [hl]                     ; opened
            ld a, DLG_EMPTY
            ret nz
            ld a, NAMES
            call sbank
            ld a, [tc_id]
            ld l, a
            ld h, high(N_TREAS)
            ld a, [hl]
            ld [dlg_item], a
            cp $1C
            jr nc, .ni
            add a, low(ITEMS)               ; an item: one more, up to 99
            ld l, a
            ld h, high(ITEMS)
            ld a, [hl]
            cp 99
            jr nc, .o1
            inc [hl]
.o1:        call tc_open
            ld a, [dlg_item]
            cp $16                          ; key items: the fanfare, others the jingle
            ld a, 1
            jr c, .o2
            inc a
.o2:        ld [dlgsfx], a
            ld a, DLG_TCGET
            ret
.ni:        cp $44
            jr nc, .nw
            sub $1B                         ; a weapon: 1-based index into a free slot
            ld b, a
            ld hl, C_WPNSLOT
            jr .find
.nw:        cp $6C
            jr nc, .gold
            sub $43                         ; armour
            ld b, a
            ld hl, C_WPNSLOT + 16
.find:      ld a, COMMON
            call sbank
            ld c, 16
.f:         ld a, [hl+]
            ld e, a
            ld d, high(ch_stats)
            ld a, [de]
            and a
            jr z, .got
            dec c
            jr nz, .f
            ld a, DLG_FULL
            ret
.got:       ld a, b
            ld [de], a
            jr .jg
.gold:      ld l, a                         ; gold: the item's price (FF1 LoadPrice)
            ld h, 0
            add hl, hl
            ld de, N_PRICE
            add hl, de
            ld a, [hl+]
            ld c, a
            ld b, [hl]
            call add_gold
.jg:        call tc_open
            ld a, 2
            ld [dlgsfx], a
            ld a, DLG_TCGET
            ret
tc_open:    ld a, [tc_id]
            ld l, a
            ld h, high(game_flags)
            set 2, [hl]
            ret

; gold += BC (at most 999999)
add_gold:   ld hl, GOLD
            ld a, [hl]
            add a, c
            ld [hl+], a
            ld a, [hl]
            adc a, b
            ld [hl+], a
            ld a, [hl]
            adc a, 0
            ld [hl], a
            cp $0F                          ; 1000000 = $0F4240
            jr c, .ok
            jr nz, .max
            dec hl
            ld a, [hl-]
            cp $42
            jr c, .ok
            jr nz, .max
            ld a, [hl]
            cp $40
            ret c
.max:       ld hl, GOLD                     ; 999999 = $0F423F
            ld a, $3F
            ld [hl+], a
            ld a, $42
            ld [hl+], a
            ld [hl], $0F
.ok:        ret


section wram, $CCA0
talk_id:    ds 1
talk_slot:  ds 1
talk_d:     ds 4
dlgsfx:     ds 1
pend_tele:  ds 1
pend_telef: ds 1
pend_btl:   ds 1
pend_btlf:  ds 1

section wram, $CC90
tc_id:      ds 1
dlg_item:   ds 1
ml_keep:    ds 1
tprop_now:  ds 1
shop_arg:   ds 1
